const assets=[{"id": "archer", "label": "궁수", "facing": "side", "note": "무기를 잡은 손과 빈 팔의 교대, 발 디딤과 머리 흔들림을 확인해 주세요.", "sheet": "data:image/png;base64,", "json": "data:application/json;base64,", "frames": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"]}, {"id": "gunner", "label": "총병", "facing": "side", "note": "무기를 잡은 손과 빈 팔의 교대, 발 디딤과 머리 흔들림을 확인해 주세요.", "sheet": "data:image/png;base64,", "json": "data:application/json;base64,", "frames": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"]}, {"id": "cannon_crew", "label": "대포병", "facing": "side", "note": "무기를 잡은 손과 빈 팔의 교대, 발 디딤과 머리 흔들림을 확인해 주세요.", "sheet": "data:image/png;base64,", "json": "data:application/json;base64,", "frames": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"]}, {"id": "wizard", "label": "마법사", "facing": "side", "note": "밤색 머리는 아직 후보입니다. 지팡이 잡은 팔은 제한하고 빈 팔만 흔듭니다.", "sheet": "data:image/png;base64,", "json": "data:application/json;base64,", "frames": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"]}, {"id": "ogre", "label": "오우거", "facing": "front", "note": "무기를 잡은 손과 빈 팔의 교대, 발 디딤과 머리 흔들림을 확인해 주세요.", "sheet": "data:image/png;base64,", "json": "data:application/json;base64,", "frames": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"]}, {"id": "ladder_goblin", "label": "사다리 고블린", "facing": "front", "note": "두 손으로 사다리를 잡고 있어 팔은 제한되며 다리와 무게 이동을 봅니다.", "sheet": "data:image/png;base64,", "json": "data:application/json;base64,", "frames": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"]}];
const config={fps:6,move:false,pivot:false,small:false};
const players=[];
const get=id=>document.getElementById(id);
let lastTime=null;
function stepPlayer(p,step=1){p.frame=(p.frame+step+4)%4;render(p);}
function setFrame(p,index){p.playing=false;p.acc=0;p.frame=index;render(p);}
function render(p){
 const c=p.ctx,w=p.canvas.width,h=p.canvas.height;c.clearRect(0,0,w,h);c.imageSmoothingEnabled=false;
 if(!p.ready)return;
 const scale=config.small?.42:1;let rootX=w/2,rootY=h-32;
 if(config.move){if(p.asset.facing==='side'){const distance=w+256*scale,phase=(p.travel+distance/2)%distance;rootX=p.right?-128*scale+phase:w+128*scale-phase;}else {const span=h+384*scale;rootY=-32*scale+((p.travel+h-32+32*scale)%span);}}
 c.save();c.translate(rootX,rootY);if(p.right&&p.asset.facing==='side')c.scale(-1,1);
 c.drawImage(p.image,p.frame*256,0,256,384,-128*scale,-352*scale,256*scale,384*scale);c.restore();
 if(config.pivot){c.strokeStyle='#ff7777';c.beginPath();c.moveTo(rootX-6,rootY);c.lineTo(rootX+6,rootY);c.moveTo(rootX,rootY-6);c.lineTo(rootX,rootY+6);c.stroke();}
 p.frameLabel.textContent='프레임 '+(p.frame+1)+'/4 · '+(p.playing?'재생':'정지');p.playButton.textContent=p.playing?'정지':'재생';
 p.frameButtons.forEach((b,i)=>b.classList.toggle('active',i===p.frame));
}
function animate(now){const dt=lastTime===null?0:Math.min(.2,Math.max(0,(now-lastTime)/1000));lastTime=now;
 for(const p of players){if(p.playing&&p.ready){p.acc+=dt*config.fps;const steps=Math.floor(p.acc);if(steps>0){p.frame=(p.frame+steps)%4;p.acc-=steps;}p.travel+=dt*(p.asset.facing==='side'?75:35);}render(p);}requestAnimationFrame(animate);}
function createPlayer(asset){const card=document.createElement('section');card.className='card';card.dataset.character=asset.id;
 const title=document.createElement('h2');title.textContent=asset.label+' · '+(asset.facing==='side'?'좌우 걷기':'정면 접근');card.appendChild(title);
 const note=document.createElement('p');note.className='notes';note.textContent=asset.note;card.appendChild(note);
 const stage=document.createElement('div');stage.className='stage';const canvas=document.createElement('canvas');canvas.width=512;canvas.height=384;stage.appendChild(canvas);card.appendChild(stage);
 const p={asset,canvas,ctx:canvas.getContext('2d'),image:new Image(),frame:0,playing:true,ready:false,acc:0,right:false,travel:0,frameButtons:[]};
 const row=document.createElement('div');row.className='row';const add=(text,fn)=>{const b=document.createElement('button');b.textContent=text;b.onclick=fn;row.appendChild(b);return b;};
 p.playButton=add('정지',()=>{p.playing=!p.playing;p.acc=0;render(p);});add('이전',()=>{p.playing=false;stepPlayer(p,-1);});add('다음',()=>{p.playing=false;stepPlayer(p,1);});
 if(asset.facing==='side'){add('왼쪽',()=>{p.right=false;p.travel=0;render(p);});add('오른쪽',()=>{p.right=true;p.travel=0;render(p);});}
 p.frameLabel=document.createElement('span');p.frameLabel.className='frameLabel';row.appendChild(p.frameLabel);card.appendChild(row);
 const frames=document.createElement('div');frames.className='frames';asset.frames.forEach((src,i)=>{const b=document.createElement('button');b.dataset.frame=i+1;const im=document.createElement('img');im.src=src;im.alt=asset.label+' 프레임 '+(i+1);b.appendChild(im);b.appendChild(document.createTextNode(String(i+1)));b.onclick=()=>setFrame(p,i);frames.appendChild(b);p.frameButtons.push(b);});card.appendChild(frames);
 const links=document.createElement('p');for(const [label,url,file]of [['격자 PNG',asset.sheet,asset.id+'_walk4_grid.png'],['규격 JSON',asset.json,asset.id+'_walk4_grid.json']]){const a=document.createElement('a');a.textContent=label;a.href=url;a.download=file;links.appendChild(a);}card.appendChild(links);
 get('cards').appendChild(card);players.push(p);
 p.image.onload=()=>{p.ready=true;render(p);};p.image.onerror=()=>{note.classList.add('error');note.textContent='이미지 로드 실패: '+asset.label;};p.image.src=asset.sheet;
}
assets.forEach(createPlayer);
get('playAll').onclick=()=>players.forEach(p=>{p.playing=true;p.acc=0;render(p);});get('pauseAll').onclick=()=>players.forEach(p=>{p.playing=false;render(p);});
get('nextAll').onclick=()=>players.forEach(p=>{p.playing=false;stepPlayer(p,1);});get('firstAll').onclick=()=>players.forEach(p=>setFrame(p,0));
get('fps').onchange=()=>{config.fps=Number(get('fps').value);players.forEach(p=>p.acc=0);};
get('move').onchange=()=>{config.move=get('move').checked;players.forEach(p=>{p.travel=0;render(p);});};
get('pivot').onchange=()=>{config.pivot=get('pivot').checked;players.forEach(render);};
get('size').onchange=()=>{config.small=get('size').value==='small';document.body.classList.toggle('small',config.small);players.forEach(render);};
get('background').onchange=()=>{document.body.classList.remove('light','checker');if(get('background').value!=='dark')document.body.classList.add(get('background').value);};
get('filter').onchange=()=>{for(const card of get('cards').children)card.hidden=get('filter').value!=='all'&&card.dataset.character!==get('filter').value;};
requestAnimationFrame(animate);
